mod response_schema;

use std::{fs, process::Command};

use tempfile::TempDir;
use uuid::{Uuid, Variant, Version};

#[test]
fn generates_fresh_uuid_v7_without_configuration_database_or_files() -> anyhow::Result<()> {
    let tmp = TempDir::new()?;
    let mut generated = Vec::new();
    for _ in 0..2 {
        let output = Command::new(env!("CARGO_BIN_EXE_exposed"))
            .current_dir(tmp.path())
            .env("DATABASE_URL", "invalid-url")
            .args(["data", "util", "uuid-v7"])
            .output()?;
        assert_eq!(
            output.status.code(),
            Some(0),
            "{}",
            String::from_utf8_lossy(&output.stderr)
        );
        assert!(output.stderr.is_empty());
        let payload: serde_json::Value = serde_json::from_slice(&output.stdout)?;
        assert_eq!(payload.as_object().unwrap().len(), 1);
        let uuid = Uuid::parse_str(payload["uuid"].as_str().unwrap())?;
        assert_eq!(uuid.get_version(), Some(Version::SortRand));
        assert_eq!(uuid.get_variant(), Variant::RFC4122);
        response_schema::validate(
            &["data", "util", "uuid-v7"],
            "Success JSON schema:",
            &payload,
        );
        generated.push(uuid);
    }
    assert_ne!(generated[0], generated[1]);
    assert_eq!(fs::read_dir(tmp.path())?.count(), 0);
    Ok(())
}
use std::process::Command;

use clap::Parser;
use exposed::inbound::cli::ExposedCli;
use tempfile::TempDir;

const COMMANDS: &[&[&str]] = &[
    &["data", "util", "latest"],
    &["data", "util", "copy-latest-raw"],
    &["data", "declarations", "fetch"],
    &["data", "declarations", "clean"],
    &["data", "declarations", "resolve"],
    &["data", "declarations", "load"],
    &["data", "members", "fetch"],
    &["data", "members", "load"],
];

#[test]
fn commands_accept_named_config() {
    for command in COMMANDS {
        let mut args = ["exposed"]
            .into_iter()
            .chain(command.iter().copied())
            .chain(["--config", "config.yaml"])
            .collect::<Vec<_>>();
        if *command != ["data", "util", "latest"] {
            args.extend(["--ingestion-key", "00000000-0000-4000-8000-000000000001"]);
        }
        assert!(ExposedCli::try_parse_from(args).is_ok(), "{command:?}");
    }
}

#[test]
fn commands_require_named_config() -> anyhow::Result<()> {
    let temporary = TempDir::new()?;
    for command in COMMANDS {
        for positional_config in [false, true] {
            let mut process = Command::new(env!("CARGO_BIN_EXE_exposed"));
            process.current_dir(temporary.path()).args(*command);
            if positional_config {
                process.arg("config.yaml");
            }
            let output = process.output()?;
            assert_eq!(output.status.code(), Some(2), "{command:?}");
            assert!(output.stdout.is_empty(), "{command:?}");
            let stderr = String::from_utf8_lossy(&output.stderr);
            if positional_config {
                assert!(
                    stderr.contains("unexpected argument 'config.yaml'"),
                    "{stderr}"
                );
            } else {
                assert!(stderr.contains("--config <CONFIG>"), "{stderr}");
                assert!(stderr.contains("required arguments"), "{stderr}");
            }
        }
    }
    assert_eq!(std::fs::read_dir(temporary.path())?.count(), 0);
    Ok(())
}

#[test]
fn utility_commands_require_the_util_group_under_data() {
    for command in ["latest", "copy-latest-raw", "uuid-v7"] {
        let error =
            ExposedCli::try_parse_from(["exposed", "data", command, "--config", "config.yaml"])
                .err()
                .expect("utilities belong under data util");
        assert_eq!(error.kind(), clap::error::ErrorKind::InvalidSubcommand);
    }
}

#[test]
fn long_help_documents_only_selected_stage_without_reading_configuration() -> anyhow::Result<()> {
    let temporary = TempDir::new()?;
    for command in COMMANDS {
        let output = Command::new(env!("CARGO_BIN_EXE_exposed"))
            .current_dir(temporary.path())
            .env_remove("DATABASE_URL")
            .args(*command)
            .args(["--config", "missing.yaml", "--help"])
            .output()?;
        assert!(output.status.success(), "{command:?}");
        assert!(output.stderr.is_empty());
        let help = String::from_utf8(output.stdout)?
            .split_whitespace()
            .collect::<Vec<_>>()
            .join(" ");
        assert!(
            help.contains("Path to a YAML configuration file."),
            "{help}"
        );
        assert!(
            help.contains("Relative data_dir paths resolve against the current working directory.")
        );
        assert!(help.contains("data_dir (string, required)"), "{help}");
        assert!(!help.contains("JSON schema:"));
        let database = matches!(
            *command,
            ["data", "declarations", "fetch" | "load"] | ["data", "members", "load"]
        );
        assert_eq!(help.contains("DATABASE_URL"), database, "{help}");
        let fetch = command.last() == Some(&"fetch");
        assert_eq!(
            help.contains("batch_size (integer, required)"),
            fetch,
            "{help}"
        );
        let resolve = command.last() == Some(&"resolve");
        assert_eq!(
            help.contains("candidate_budget (integer, optional, default 1000000)"),
            resolve,
            "{help}"
        );
    }
    assert_eq!(std::fs::read_dir(temporary.path())?.count(), 0);
    Ok(())
}

#[test]
fn existing_stages_require_keys_before_reading_files_or_environment() -> anyhow::Result<()> {
    let temporary = TempDir::new()?;
    for command in COMMANDS
        .iter()
        .filter(|command| command.get(1) != Some(&"util") && command.last() != Some(&"fetch"))
    {
        let output = Command::new(env!("CARGO_BIN_EXE_exposed"))
            .current_dir(temporary.path())
            .env_remove("DATABASE_URL")
            .args(*command)
            .args(["--config", "missing.yaml"])
            .output()?;
        assert_eq!(output.status.code(), Some(2), "{command:?}");
        let error = String::from_utf8_lossy(&output.stderr);
        assert!(error.contains("--ingestion-key <INGESTION_KEY>"), "{error}");
        assert!(!error.contains("unable to read"));
        assert!(!error.contains("DATABASE_URL must"));
    }
    assert_eq!(std::fs::read_dir(temporary.path())?.count(), 0);
    Ok(())
}

#[test]
fn invalid_keys_report_uuid_errors() {
    let error = ExposedCli::try_parse_from([
        "exposed",
        "data",
        "members",
        "load",
        "--config",
        "missing.yaml",
        "--ingestion-key",
        "bad",
    ])
    .err()
    .unwrap()
    .to_string();
    assert!(error.contains("invalid ingestion ID"), "{error}");
    assert!(!error.contains("invalid stage"));
}

#[test]
fn every_yaml_config_error_names_selected_path() -> anyhow::Result<()> {
    let temporary = TempDir::new()?;
    let path = temporary.path().join("selected.yaml");
    for contents in [
        None,
        Some("data_dir: ["),
        Some("batch_size: wrong\ndata_dir: datasets\n"),
    ] {
        if let Some(contents) = contents {
            std::fs::write(&path, contents)?;
        }
        for command in COMMANDS {
            if contents == Some("batch_size: wrong\ndata_dir: datasets\n")
                && command.last() != Some(&"fetch")
            {
                continue;
            }
            let output = Command::new(env!("CARGO_BIN_EXE_exposed"))
                .current_dir(temporary.path())
                .env_remove("DATABASE_URL")
                .args(*command)
                .arg("--config")
                .arg(&path)
                .args(if *command == ["data", "util", "latest"] {
                    vec![]
                } else {
                    vec!["--ingestion-key", "00000000-0000-4000-8000-000000000001"]
                })
                .output()?;
            assert_eq!(output.status.code(), Some(1), "{command:?}");
            let payload: serde_json::Value = serde_json::from_slice(&output.stderr)?;
            assert!(
                payload["error"]["message"]
                    .as_str()
                    .unwrap()
                    .contains(path.to_str().unwrap()),
                "{payload}"
            );
        }
    }
    Ok(())
}

#[test]
fn member_load_missing_artifact_does_not_create_raw_directory() -> anyhow::Result<()> {
    let temporary = TempDir::new()?;
    let config = temporary.path().join("config.yaml");
    std::fs::write(&config, "data_dir: data\n")?;
    let output = Command::new(env!("CARGO_BIN_EXE_exposed"))
        .current_dir(temporary.path())
        .env("DATABASE_URL", "postgresql://invalid")
        .args(["data", "members", "load", "--config"])
        .arg(config)
        .args(["--ingestion-key", "00000000-0000-4000-8000-000000000001"])
        .output()?;
    assert_eq!(output.status.code(), Some(1));
    assert!(String::from_utf8_lossy(&output.stderr).contains("raw/members.parquet"));
    assert!(!temporary.path().join("data").exists());
    Ok(())
}

#[test]
fn documented_resolver_default_matches_yaml_parser() -> anyhow::Result<()> {
    use exposed::inbound::cli::config::DeclarationResolverConfig;

    let temporary = TempDir::new()?;
    let path = temporary.path().join("config.yaml");
    std::fs::write(&path, "data_dir: datasets\n")?;
    let config = DeclarationResolverConfig::try_from(&path)?;
    assert_eq!(config.candidate_budget, 1_000_000);
    assert_eq!(config.data_dir, std::path::PathBuf::from("datasets"));
    std::fs::write(&path, "candidate_budget: 1\n")?;
    assert!(DeclarationResolverConfig::try_from(&path).is_err());
    std::fs::write(&path, "data_dir: datasets\ncandidate_budget: 0\n")?;
    assert!(DeclarationResolverConfig::try_from(&path).is_err());
    Ok(())
}
#[path = "common/response_schema.rs"]
mod response_schema;

use clap::CommandFactory;
use exposed::inbound::cli::{DataArgs, ExposedCli, UtilArgs};
use serde_json::json;
use std::process::Command;

#[test]
fn every_command_documents_responses_without_configuration_or_side_effects() {
    for command in DataArgs::command()
        .get_subcommands()
        .filter(|command| command.get_name() != "help")
    {
        for stage in command
            .get_subcommands()
            .filter(|stage| stage.get_name() != "help")
        {
            let args = ["data", command.get_name(), stage.get_name()];
            let help = response_schema::help(&args);
            assert!(!help.contains("JSON schema:"));
            response_schema::validator(&args, "Success JSON schema:");
            response_schema::validator(&args, "Failure JSON schema:");
            let output = Command::new(env!("CARGO_BIN_EXE_exposed"))
                .args(args)
                .arg("-h")
                .output()
                .unwrap();
            assert!(output.status.success());
            assert!(!String::from_utf8_lossy(&output.stdout).contains("JSON schema:"));
        }
    }
    let output = Command::new(env!("CARGO_BIN_EXE_exposed"))
        .arg("--version")
        .output()
        .unwrap();
    assert!(output.status.success());
    assert!(String::from_utf8_lossy(&output.stdout).contains(env!("CARGO_PKG_VERSION")));
}

#[test]
fn required_nullable_fields_and_typed_values_reject_malformed_responses() {
    let latest = response_schema::validator(&["data", "util", "latest"], "Success JSON schema:");
    assert!(latest.is_valid(&json!({"ingestion": null})));
    assert!(!latest.is_valid(&json!({})));
    assert!(!latest.is_valid(&json!({"ingestion": {"ingestion_key": "bad", "path": "/data"}})));
    let clean =
        response_schema::validator(&["data", "declarations", "clean"], "Success JSON schema:");
    let mut payload = json!({"ingestion_key":"00000000-0000-4000-8000-000000000001", "path":"/data", "member_partitions":1,"declarations":2,"funders":3,"funding_entries":4});
    assert!(clean.is_valid(&payload));
    payload["declarations"] = json!("2");
    assert!(!clean.is_valid(&payload));
    let load =
        response_schema::validator(&["data", "declarations", "load"], "Success JSON schema:");
    let mut payload = json!({"ingestion_key":"00000000-0000-4000-8000-000000000001", "outcome":"imported", "declarations":2,"funders":3,"funding_entries":4});
    assert!(load.is_valid(&payload));
    payload["outcome"] = json!("unknown");
    assert!(!load.is_valid(&payload));
    let fetch =
        response_schema::validator(&["data", "declarations", "fetch"], "Success JSON schema:");
    let mut payload = json!({"ingestion_key":"00000000-0000-4000-8000-000000000001", "path":"/data", "stage":"fetch"});
    assert!(fetch.is_valid(&payload));
    payload["stage"] = json!("clean");
    assert!(!fetch.is_valid(&payload));
    let member = response_schema::validator(&["data", "members", "load"], "Success JSON schema:");
    payload["stage"] = json!("load");
    assert!(member.is_valid(&payload));
    payload["stage"] = json!("resolve");
    assert!(!member.is_valid(&payload));
    let error = response_schema::validator(&["data", "util", "latest"], "Failure JSON schema:");
    assert!(!error.is_valid(&json!({"error":{}})));
    assert!(!error.is_valid(&json!({"error":{"message":1}})));
}

#[test]
fn help_groups_pipeline_commands_and_utilities() {
    let mut root = ExposedCli::command();
    let help = root.render_long_help().to_string();
    assert!(
        !help
            .lines()
            .any(|line| line.trim_start().starts_with("util "))
    );
    let output = Command::new(env!("CARGO_BIN_EXE_exposed"))
        .args(["util", "uuid-v7"])
        .output()
        .unwrap();
    assert_eq!(output.status.code(), Some(2));
    assert!(output.stdout.is_empty());
    assert!(String::from_utf8_lossy(&output.stderr).contains("unrecognized subcommand"));
    let output = Command::new(env!("CARGO_BIN_EXE_exposed"))
        .args(["data", "util", "--help"])
        .output()
        .unwrap();
    assert!(output.status.success());
    let help = String::from_utf8(output.stdout).unwrap();
    for command in ["latest", "copy-latest-raw", "uuid-v7"] {
        assert!(
            help.lines()
                .any(|line| line.trim_start().starts_with(&format!("{command} ")))
        );
    }
    for (mut tree, expected, absent) in [
        (
            DataArgs::command(),
            &["declarations", "members", "util"][..],
            &["latest", "copy-latest-raw", "uuid-v7"][..],
        ),
        (
            UtilArgs::command(),
            &["latest", "copy-latest-raw", "uuid-v7"][..],
            &["declarations", "members"][..],
        ),
    ] {
        let help = tree.render_long_help().to_string();
        for name in expected {
            assert!(
                help.lines()
                    .any(|line| line.trim_start().starts_with(&format!("{name} "))),
                "{help}"
            );
        }
        for name in absent {
            assert!(
                !help
                    .lines()
                    .any(|line| line.trim_start().starts_with(&format!("{name} "))),
                "{help}"
            );
        }
    }
}

#[test]
fn schema_inspection_skips_dotenv_and_async_runtime_startup() -> anyhow::Result<()> {
    let temporary = tempfile::tempdir()?;
    std::fs::write(
        temporary.path().join(".env"),
        "TOKIO_WORKER_THREADS=not-a-number\n",
    )?;
    for command in [
        vec!["data", "declarations", "fetch"],
        vec!["data", "declarations", "clean"],
        vec!["data", "declarations", "resolve"],
        vec!["data", "declarations", "load"],
        vec!["data", "members", "fetch"],
        vec!["data", "members", "load"],
        vec!["data", "util", "latest"],
        vec!["data", "util", "copy-latest-raw"],
        vec!["data", "util", "uuid-v7"],
    ] {
        let output = Command::new(env!("CARGO_BIN_EXE_exposed"))
            .current_dir(temporary.path())
            .env_remove("TOKIO_WORKER_THREADS")
            .args(&command)
            .arg("--schema")
            .output()?;
        assert!(
            output.status.success(),
            "{command:?}: {}",
            String::from_utf8_lossy(&output.stderr)
        );
        assert!(output.stderr.is_empty());
        let document: serde_json::Value = serde_json::from_slice(&output.stdout)?;
        assert!(document["success"].is_object());
        assert!(document["failure"].is_object());
    }
    Ok(())
}
//! Launcher checks run in isolated processes so global subscribers and dotenv
//! never change the integration-test process's environment.

use std::process::{Command, Output};

fn server(directory: &std::path::Path, rust_log: Option<&str>) -> Output {
    let mut command = Command::new(env!("CARGO_BIN_EXE_exposed"));
    command
        .current_dir(directory)
        .arg("server")
        .env_remove("DATABASE_URL")
        .env_remove("RUST_LOG");
    if let Some(filter) = rust_log {
        command.env("RUST_LOG", filter);
    }
    command.output().unwrap()
}

#[test]
fn invalid_explicit_filter_fails_once_before_server_configuration() {
    let directory = tempfile::tempdir().unwrap();
    let output = server(directory.path(), Some("exposed["));
    assert!(!output.status.success());
    assert!(output.stdout.is_empty());
    let stderr = String::from_utf8(output.stderr).unwrap();
    assert!(stderr.starts_with("Error:"), "{stderr}");
    assert!(!stderr.contains("server.failed"), "{stderr}");
    assert!(stderr.contains("invalid filter directive"), "{stderr}");
    assert!(!stderr.contains("DATABASE_URL"));
}

#[test]
fn missing_filter_uses_default_and_startup_error_uses_plain_stderr() {
    let directory = tempfile::tempdir().unwrap();
    let output = server(directory.path(), None);
    assert!(!output.status.success());
    assert!(output.stdout.is_empty());
    let stderr = String::from_utf8(output.stderr).unwrap();
    assert!(
        stderr.starts_with("Error: reading HTTP server configuration"),
        "{stderr}"
    );
    assert!(stderr.contains("DATABASE_URL must be set"), "{stderr}");
    assert!(!stderr.contains("server.failed"), "{stderr}");
}

#[test]
fn dotenv_filter_is_loaded_before_subscriber_initialization() {
    let directory = tempfile::tempdir().unwrap();
    std::fs::write(directory.path().join(".env"), "RUST_LOG=exposed[\n").unwrap();
    let output = server(directory.path(), None);
    assert!(!output.status.success());
    assert!(output.stdout.is_empty());
    let stderr = String::from_utf8(output.stderr).unwrap();
    assert!(stderr.contains("invalid filter directive"), "{stderr}");
    assert!(!stderr.contains("DATABASE_URL"));
}

